<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice='';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{pv_require_csrf();$tamer=nxt_skin_id((int)($_POST['tamer']??1));$show=isset($_POST['memonmap'])?1:0;$messages=isset($_POST['messonoff'])?1:0;$messageNotify=isset($_POST['messnotifyonoff'])?1:0;$battleAnim=isset($_POST['battle_animation'])?1:0;$compact=isset($_POST['compact_ui'])?1:0;$stmt=$db->prepare('INSERT INTO members_options(id,tamer,memonmap,messonoff,messnotifyonoff,battle_animation,compact_ui) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE tamer=VALUES(tamer),memonmap=VALUES(memonmap),messonoff=VALUES(messonoff),messnotifyonoff=VALUES(messnotifyonoff),battle_animation=VALUES(battle_animation),compact_ui=VALUES(compact_ui)');$stmt->bind_param('iiiiiii',$uid,$tamer,$show,$messages,$messageNotify,$battleAnim,$compact);if(!$stmt->execute())throw new RuntimeException($stmt->error);$stmt->close();$stmt=$db->prepare('UPDATE members SET memonmap=?,messonoff=?,messnotifyonoff=?,created_avatar=? WHERE id=?');$stmt->bind_param('iiiii',$show,$messages,$messageNotify,$tamer,$uid);$stmt->execute();$stmt->close();$_SESSION['map_preferences']=[0,$show,$tamer];$notice='Network options saved.';dn_world_event('game','options.update','Tamer appearance and preferences updated');}catch(Throwable $e){$error=$e->getMessage();}}
$stmt=$db->prepare('SELECT COALESCE(o.tamer,m.created_avatar,1) tamer,COALESCE(o.memonmap,m.memonmap,1) memonmap,COALESCE(o.messonoff,m.messonoff,1) messonoff,COALESCE(o.messnotifyonoff,m.messnotifyonoff,1) messnotifyonoff,COALESCE(o.battle_animation,1) battle_animation,COALESCE(o.compact_ui,0) compact_ui FROM members m LEFT JOIN members_options o ON o.id=m.id WHERE m.id=?');$stmt->bind_param('i',$uid);$stmt->execute();$opt=$stmt->get_result()->fetch_assoc();$stmt->close();pv_page_start('Network Options','options.php',true);
?>
<div class="pv-game-layout"><?php pv_game_side_menu('options.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">TAMER LINK SETTINGS</span><h1>Network Options</h1><p class="pv-subtle">Control your Cyberspace avatar, presence visibility, communications and interface preferences.</p></div></div><?php if($notice):?><div class="pv-flash success"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><form class="pv-card" style="padding:20px" method="post"><?=pv_csrf_field()?><h3>Your tamer avatar</h3><p class="pv-subtle">Choose an original avatar or a character sprite extracted from Digimon World Dawn. Your choice appears throughout the game and on shared maps.</p><?php nxt_skin_picker((int)$opt['tamer']);?><div class="pv-option-list" style="margin-top:18px"><label class="pv-check-row"><input type="checkbox" name="memonmap" value="1" <?=(int)$opt['memonmap']!==0?'checked':''?>><span><strong>Shared tamer presence</strong><small>Render other online tamers in the same Cyberspace sector.</small></span></label><label class="pv-check-row"><input type="checkbox" name="messonoff" value="1" <?=(int)$opt['messonoff']!==0?'checked':''?>><span><strong>Private messages</strong><small>Keep tamer-to-tamer communications enabled.</small></span></label><label class="pv-check-row"><input type="checkbox" name="messnotifyonoff" value="1" <?=(int)$opt['messnotifyonoff']!==0?'checked':''?>><span><strong>Message notifications</strong><small>Create account notifications for incoming messages.</small></span></label><label class="pv-check-row"><input type="checkbox" name="battle_animation" value="1" <?=(int)$opt['battle_animation']!==0?'checked':''?>><span><strong>Interface motion</strong><small>Animate partner sprites, holograms and ambient data streams.</small></span></label><label class="pv-check-row"><input type="checkbox" name="compact_ui" value="1" <?=(int)$opt['compact_ui']!==0?'checked':''?>><span><strong>Compact interface</strong><small>Use tighter cards and spacing throughout your command center.</small></span></label></div><button class="pv-button" type="submit">Save Network Options</button></form></section></main></div><?php pv_page_end(); ?>
